// Декодер base64 → ArrayBuffer (совместим со старыми браузерами)
window.EMBEDDED_TEMPLATES._toBuffer = function(b64) {
    var bin = atob(b64);
    var len = bin.length;
    var bytes = new Uint8Array(len);
    for (var i = 0; i < len; i++) bytes[i] = bin.charCodeAt(i);
    return bytes.buffer;
};
